mapper.sql:
WHERE h.DELETED_YN = 'N' AND EXISTS ( SELECT 1 FROM SHIP_INSTRUCTION_LINE l WHERE l.SHIP_INSTRUCTION_ID = h.SHIP_INSTRUCTION_ID AND l.DELETED_YN = 'N' )
AND h.PROGRESS_STATUS = #{progressStatus}
AND ( UPPER(h.SHIP_INSTRUCTION_NO) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR TO_CHAR(h.BUSINESS_DATE, 'YYYY/MM/DD') LIKE '%' || #{criteria.keyword} || '%' OR UPPER(h.PARTNER_NAME) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR UPPER(h.ASSIGNEE_NAME) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR EXISTS ( SELECT 1 FROM SHIP_INSTRUCTION_LINE l LEFT JOIN ITEM i ON i.ITEM_ID = l.ITEM_ID WHERE l.SHIP_INSTRUCTION_ID = h.SHIP_INSTRUCTION_ID AND l.DELETED_YN = 'N' AND ( UPPER(i.ITEM_CODE) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR UPPER(l.ITEM_NAME) LIKE '%' || UPPER(#{criteria.keyword}) || '%' ) ) )
